        nav=row();nav.setBackgroundColor(NAVY);nav.setPadding(dp(4),dp(4),dp(4),dp(4));String[] names={"Home","Bills","Customers","Items","More"},routes={"home","invoices","customers","products","settings"};for(int j=0;j<names.length;j++){final String route=routes[j];TextView t=txt(names[j],11,WHITE,true);t.setGravity(Gravity.CENTER);t.setMinHeight(dp(52));t.setOnClickListener(v->navigate(route));weight(nav,t);}add(panel,nav);
