    void newBill(String kind){if(editing){confirm("Discard draft?","Start a new document?",()->{editing=false;newBill(kind);});return;}JSONObject b=copy(sub(db(),"business"));draft=obj("id",id(),"number",("quote".equals(kind)?"QT":str(b,"prefix").isEmpty()?"INV":str(b,"prefix"))+"-"+String.format(Locale.US,"%04d",db().optLong("next",1)),"date",today(),"dueDate","","taxMode","none","kind",kind,"business",b,"customer",customer(),"items",new JSONArray(),"paid",0,"payment","Cash","notes","Thank you for your business!");if("product".equals(kind))put(sub(draft,"customer"),"name","Walk-in customer");editing=true;show("edit");}
