    void editor(){if(draft==null){show("home");return;}title(quote(draft)?"Create quotation":"Create bill","Shop details, items and payment");LinearLayout c=card(body);add(c,txt("Shop / Business",18,INK,true));shopFields(c,sub(draft,"business"));CheckBox remember=new CheckBox(a);remember.setText("Save shop details for future bills");remember.setChecked(draft.optBoolean("rememberShop"));remember.setOnCheckedChangeListener((v,on)->put(draft,"rememberShop",on));add(c,remember);
        c=card(body);bind(c,"Bill number",draft,"number",TEXT);bind(c,"Date (YYYY-MM-DD)",draft,"date",TEXT);bind(c,quote(draft)?"Valid until":"Due date (optional)",draft,"dueDate",TEXT);select(c,"Tax type",new String[]{"Non-GST","CGST + SGST","IGST"},new String[]{"none","local","inter"},str(draft,"taxMode"),v->put(draft,"taxMode",v));
        c=card(body);pair(c,"Select customer",()->pick("customers",x->{put(draft,"customer",copy(x));show("edit");}),"New customer",()->{put(draft,"customer",customer());show("edit");});customerFields(c,sub(draft,"customer"));
        c=card(body);add(c,txt("Products / services",18,INK,true));pair(c,"Search catalogue",()->pick("products",x->{JSONObject p=copy(x);put(p,"productId",str(x,"id"));put(p,"qty",1);if(!p.has("discount"))put(p,"discount",0);arr(draft,"items").put(p);show("edit");}),"Add custom item",()->itemDialog(null,-1));
        btn(c,"Add new catalogue product",false,()->directoryDialog(false,null,true));
        JSONArray items=arr(draft,"items");for(int j=0;j<items.length();j++){final int idx=j;JSONObject x=items.optJSONObject(j);LinearLayout r=card(c);add(r,txt(str(x,"name"),16,INK,true));add(r,txt(quantity(n(x,"qty"))+" "+str(x,"unit")+" × "+money(n(x,"rate"))+" · Discount "+quantity(n(x,"discount"))+"%",13,MUTED,false));pair(r,"Edit item",()->itemDialog(x,idx),"Remove",()->{arr(draft,"items").remove(idx);show("edit");});}
        c=card(body);if(!quote(draft)){bindNumber(c,"Amount received (₹)",draft,"paid");select(c,"Payment method",new String[]{"Cash","UPI","Card","Bank transfer","Other"},new String[]{"Cash","UPI","Card","Bank transfer","Other"},str(draft,"payment"),v->put(draft,"payment",v));btn(c,"Mark fully paid",false,()->{put(draft,"paid",new Totals(draft).total);show("edit");});}bind(c,"Notes / terms",draft,"notes",MULTI);add(c,txt("Current total: "+money(new Totals(draft).total),20,ORANGE,true));btn(c,"Save & preview",true,()->safe(this::saveBill));}
    interface Choice {void selected(JSONObject o);}
    void pick(String type,Choice callback){LinearLayout l=col();l.setPadding(dp(16),dp(8),dp(16),dp(8));EditText q=field(l,"Search name, phone, SKU, HSN","",TEXT);ScrollView scroll=new ScrollView(a);LinearLayout rows=col();scroll.addView(rows);l.addView(scroll,new LayoutParams(-1,dp(280)));AlertDialog dialog=new AlertDialog.Builder(a).setTitle("customers".equals(type)?"Choose customer":"Choose product").setView(l).setNegativeButton("Cancel",null).create();Runnable update=()->{rows.removeAllViews();JSONArray list=arr(db(),type);String term=val(q).toLowerCase(Locale.ROOT);int shown=0;for(int j=0;j<list.length()&&shown<100;j++){JSONObject o=list.optJSONObject(j);String hay=(str(o,"name")+" "+str(o,"phone")+" "+str(o,"sku")+" "+str(o,"hsn")+" "+str(o,"category")).toLowerCase(Locale.ROOT);if(!hay.contains(term))continue;shown++;btn(rows,str(o,"name")+("products".equals(type)?" · "+money(n(o,"rate")):" · "+str(o,"phone")),false,()->{dialog.dismiss();callback.selected(o);});}if(shown==0)add(rows,txt("No matching records.",14,MUTED,false));};watch(q,v->update.run());update.run();dialog.show();}
    JSONObject blankProduct(){return obj("id",id(),"name","","hsn","","unit","pcs","rate",0,"gst",0,"discount",0,"sku","","category","");}
    void itemDialog(JSONObject existing,int index){JSONObject p=existing==null?blankProduct():copy(existing);if(!p.has("qty"))put(p,"qty",1);LinearLayout c=col();c.setPadding(dp(16),dp(8),dp(16),dp(8));EditText name=field(c,"Description *",str(p,"name"),TEXT),qty=field(c,"Quantity",quantity(n(p,"qty")),NUM),rate=field(c,"Rate ₹",quantity(n(p,"rate")),NUM),discount=field(c,"Discount %",quantity(n(p,"discount")),NUM),gst=field(c,"GST %",quantity(n(p,"gst")),NUM),unit=field(c,"Unit",str(p,"unit"),TEXT),hsn=field(c,"HSN / SAC",str(p,"hsn"),TEXT),sku=field(c,"SKU",str(p,"sku"),TEXT);ScrollView scroll=new ScrollView(a);scroll.addView(c);AlertDialog d=new AlertDialog.Builder(a).setTitle("Bill item").setView(scroll).setNegativeButton("Cancel",null).setPositiveButton("Save",null).create();d.setOnShowListener(v->d.getButton(-1).setOnClickListener(w->safe(()->{require(!val(name).isEmpty()&&valNum(qty)>0,"Enter item name and positive quantity");require(valNum(discount)<=100&&valNum(gst)<=100,"Invalid percentage");put(p,"name",val(name));put(p,"qty",valNum(qty));put(p,"rate",valNum(rate));put(p,"discount",valNum(discount));put(p,"gst",valNum(gst));put(p,"unit",val(unit));put(p,"hsn",val(hsn));put(p,"sku",val(sku));if(index<0)arr(draft,"items").put(p);else arr(draft,"items").put(index,p);d.dismiss();show("edit");})));d.show();}
    void saveBill()throws Exception{JSONObject i=copy(draft);require(!str(sub(i,"business"),"name").isEmpty(),"Enter shop name");require(!str(sub(i,"customer"),"name").isEmpty(),"Enter customer name");require(!str(i,"number").isEmpty()&&dateValid(str(i,"date")),"Enter valid bill number and date");require(str(i,"dueDate").isEmpty()||(dateValid(str(i,"dueDate"))&&str(i,"dueDate").compareTo(str(i,"date"))>=0),"Invalid due date");require(arr(i,"items").length()>0,"Add at least one item");require("none".equals(str(i,"taxMode"))||!str(sub(i,"business"),"gstin").isEmpty(),"GSTIN is required for GST bills");for(int j=0;j<arr(i,"items").length();j++){JSONObject x=arr(i,"items").getJSONObject(j);require(!str(x,"name").isEmpty(),"Enter item name");}require(finite(i.opt("paid"))&&n(i,"paid")<=new Totals(i).total,"Invalid received amount");JSONObject next=copy(db());JSONArray invoices=arr(next,"invoices");JSONObject old=find(invoices,str(i,"id"));for(int j=0;j<invoices.length();j++){JSONObject x=invoices.getJSONObject(j);require(str(x,"id").equals(str(i,"id"))||!str(x,"number").equalsIgnoreCase(str(i,"number")),"Bill number already exists");}
        i.remove("signature");i.remove("rememberShop");if(quote(i))put(i,"paid",0);stock(next,old,i);upsert(invoices,i);if(old==null)put(next,"next",next.optLong("next",1)+1);if(draft.optBoolean("rememberShop"))put(next,"business",copy(sub(i,"business")));store.commit(next);a.tell("Saved");open(str(i,"id"));}
    boolean dateValid(String date){try{java.text.SimpleDateFormat f=new java.text.SimpleDateFormat("yyyy-MM-dd",Locale.US);f.setLenient(false);return date.matches("[0-9]{4}-[0-9]{2}-[0-9]{2}")&&f.parse(date)!=null;}catch(Exception e){return false;}}
    void preview(){JSONObject i=bill();if(i==null){show("invoices");return;}title(quote(i)?"Quotation preview":"Bill preview",str(i,"number"));LinearLayout actions=card(body);pair(actions,"Download PDF",()->export(i,"save"),"Share PDF",()->export(i,"share"));pair(actions,"Save HD JPG",()->export(i,"saveJpg"),"Share JPG",()->export(i,"shareJpg"));btn(actions,"Print A4",false,()->export(i,"print"));pair(actions,"Edit bill / Shop",()->{Runnable edit=()->{draft=copy(i);draft.remove("signature");editing=true;show("edit");};if(i.has("signature"))confirm("Edit signed bill?","Saving changes removes the existing signature.",edit);else edit.run();},"Add / edit signature",()->sign(i,false));pair(actions,quote(i)?"Convert to invoice":"Record payment",()->{if(quote(i))duplicate(i,true);else payment(i);},"Duplicate",()->duplicate(i,false));if(!quote(i))btn(actions,"Share summary",false,()->a.shareSummary(str(i,"number")+" · "+str(sub(i,"business"),"name")+" · "+money(new Totals(i).total)+" · Due "+money(new Totals(i).due)));btn(actions,"Delete",false,()->confirm("Delete document?","This restores linked stock and removes the local record.",()->safe(()->{JSONObject next=copy(db());JSONObject old=find(arr(next,"invoices"),str(i,"id"));stock(next,old,null);remove(arr(next,"invoices"),str(i,"id"));store.commit(next);show(quote(i)?"quotes":"invoices");})));
        JSONObject p=payload(i);LinearLayout c=card(body);View accent=new View(a);accent.setBackgroundColor(0xffff9933);c.addView(accent,new LayoutParams(-1,dp(5)));ImageView logo=new ImageView(a);logo.setAdjustViewBounds(true);logo.setMaxHeight(dp(70));displayLogo(logo,str(p,"logo"));add(c,logo);add(c,txt(str(p,"business").isEmpty()?"Shop name not set":str(p,"business"),25,ORANGE,true));lines(c,arr(p,"businessInfo"));if(!str(p,"title").isEmpty())add(c,txt(str(p,"title"),15,ORANGE,true));add(c,txt("No. "+str(p,"number")+"  ·  "+str(p,"date"),13,MUTED,false));if(!str(p,"dueDate").isEmpty())add(c,txt("Due / valid until: "+str(p,"dueDate"),13,MUTED,false));gap(c,12);add(c,txt("BILL TO",12,ORANGE,true));add(c,txt(str(p,"customer"),18,INK,true));lines(c,arr(p,"customerInfo"));add(c,txt(str(p,"payment"),14,ORANGE,true));gap(c,10);JSONArray rows=arr(p,"rows");for(int j=0;j<rows.length();j++){JSONArray r=rows.optJSONArray(j);LinearLayout item=col();bg(item,0xfffff5e9,9);item.setPadding(dp(10),dp(7),dp(10),dp(7));add(item,txt(r.optString(0),15,INK,true));add(item,txt(r.optString(1)+" × "+r.optString(2)+" · Disc "+r.optString(3)+" · GST "+r.optString(4),12,MUTED,false));add(item,txt(r.optString(5),17,ORANGE,true));add(c,item);gap(c,5);}JSONArray sums=arr(p,"summary");for(int j=0;j<sums.length();j++){JSONArray r=sums.optJSONArray(j);LinearLayout line=row();boolean total="Grand total".equals(r.optString(0));if(total){bg(line,0xffffedd7,10);line.setPadding(dp(8),dp(10),dp(8),dp(10));}weight(line,txt(r.optString(0),total?18:14,INK,total));line.addView(txt(r.optString(1),total?19:14,ORANGE,true));add(c,line);}lines(c,arr(p,"paymentInfo"));add(c,txt(str(p,"notes"),13,MUTED,false));if(i.has("signature")){SignaturePad pad=new SignaturePad(a,arr(i,"signature"),false);c.addView(pad,new LayoutParams(-1,dp(95)));}add(c,txt("Authorised signatory",13,INK,true));}
