    void duplicate(JSONObject i,boolean convert){draft=copy(i);draft.remove("signature");draft.remove("stockMoves");put(draft,"id",id());if(convert)put(draft,"kind","standard");String prefix=quote(draft)?"QT":str(sub(db(),"business"),"prefix");put(draft,"number",(prefix.isEmpty()?"INV":prefix)+"-"+String.format(Locale.US,"%04d",db().optLong("next",1)));put(draft,"date",today());put(draft,"dueDate","");put(draft,"paid",0);editing=true;show("edit");}
    void payment(JSONObject i){LinearLayout l=col();l.setPadding(dp(16),0,dp(16),0);EditText e=field(l,"Additional received amount ₹",quantity(new Totals(i).due),NUM);AlertDialog d=new AlertDialog.Builder(a).setTitle("Record payment").setMessage(i.has("signature")?"Changing payment removes the existing signature.":"Enter payment received.").setView(l).setNegativeButton("Cancel",null).setPositiveButton("Save",null).create();d.setOnShowListener(v->d.getButton(-1).setOnClickListener(w->safe(()->{double amount=valNum(e);require(amount>0&&amount<=new Totals(i).due,"Invalid payment amount");JSONObject next=copy(db()),x=find(arr(next,"invoices"),str(i,"id"));put(x,"paid",round(new Totals(i).paid+amount));x.remove("signature");store.commit(next);d.dismiss();show("preview");})));d.show();}
    void directory(boolean customer){title(customer?"Customers":"Products & services",customer?"Manage contacts":"Manage reusable catalogue");pair(body,customer?"Add customer":"Add product",()->directoryDialog(customer,null,false),customer?"Customer ledger":"Inventory",()->show(customer?"ledger":"inventory"));EditText q=field(body,"Search records","",TEXT);LinearLayout list=col();add(body,list);Runnable update=()->{list.removeAllViews();JSONArray a=arr(db(),customer?"customers":"products");String term=val(q).toLowerCase(Locale.ROOT);for(int j=0;j<a.length();j++){JSONObject x=a.optJSONObject(j);if(!(str(x,"name")+" "+str(x,"phone")+" "+str(x,"sku")+" "+str(x,"hsn")+" "+str(x,"category")).toLowerCase(Locale.ROOT).contains(term))continue;LinearLayout c=card(list);add(c,txt(str(x,"name"),17,INK,true));add(c,txt(customer?str(x,"phone")+" · "+str(x,"address"):money(n(x,"rate"))+" · "+str(x,"unit")+" · SKU "+str(x,"sku"),13,MUTED,false));pair(c,"Edit",()->directoryDialog(customer,x,false),"Delete",()->confirm("Delete record?","Saved bills remain unchanged.",()->safe(()->{JSONObject next=copy(db());if(!customer){JSONArray bills=arr(next,"invoices");for(int k=0;k<bills.length();k++)require(find(arr(bills.optJSONObject(k),"stockMoves"),str(x,"id"))==null,"Product linked to stock history");}remove(arr(next,customer?"customers":"products"),str(x,"id"));store.commit(next);show(screen);})));}
        };watch(q,v->update.run());update.run();}
    void directoryDialog(boolean customer,JSONObject existing,boolean addToBill){JSONObject x=existing==null?(customer?customer():blankProduct()):copy(existing);if(!x.has("id"))put(x,"id",id());LinearLayout l=col();l.setPadding(dp(16),dp(8),dp(16),dp(8));if(customer)customerFields(l,x);else{bind(l,"Product name *",x,"name",TEXT);bindNumber(l,"Selling price ₹",x,"rate");bindNumber(l,"GST %",x,"gst");bindNumber(l,"Discount %",x,"discount");bind(l,"HSN / SAC",x,"hsn",TEXT);bind(l,"SKU / barcode",x,"sku",TEXT);bind(l,"Category",x,"category",TEXT);bind(l,"Unit",x,"unit",TEXT);}ScrollView s=new ScrollView(a);s.addView(l);AlertDialog d=new AlertDialog.Builder(a).setTitle(customer?"Customer details":"Product details").setView(s).setNegativeButton("Cancel",null).setPositiveButton("Save",null).create();d.setOnShowListener(v->d.getButton(-1).setOnClickListener(w->safe(()->{require(!str(x,"name").isEmpty(),"Name required");if(!customer){require(n(x,"gst")<=100&&n(x,"discount")<=100,"Invalid percentage");}JSONObject next=copy(db());upsert(arr(next,customer?"customers":"products"),x);store.commit(next);d.dismiss();if(addToBill){JSONObject p=copy(x);put(p,"productId",str(x,"id"));put(p,"qty",1);arr(draft,"items").put(p);show("edit");}else show(screen);})));d.show();}
    void productStudio(){title("Product Bill Studio","Retail and wholesale billing");btn(body,"+ New product bill",true,()->newBill("product"));btn(body,"Manage catalogue",false,()->show("products"));btn(body,"Search product & start bill",false,()->pick("products",x->{newBill("product");JSONObject p=copy(x);put(p,"productId",str(x,"id"));put(p,"qty",1);if(!p.has("discount"))put(p,"discount",0);arr(draft,"items").put(p);show("edit");}));documentList("product");}
    void documentList(String kind){JSONArray a=arr(db(),"invoices");for(int j=a.length()-1;j>=0;j--){JSONObject i=a.optJSONObject(j);if(!kind.equals(str(i,"kind")))continue;btn(body,str(i,"number")+" · "+str(sub(i,"customer"),"name")+" · "+money(new Totals(i).total),false,()->open(str(i,"id")));}}
