    void inventory(){title("Inventory & stock","Catalogue-linked bills update tracked stock");btn(body,"Add product",true,()->directoryDialog(false,null,false));JSONArray products=arr(db(),"products");double cost=0,value=0;int tracked=0,low=0;for(int j=0;j<products.length();j++){JSONObject p=products.optJSONObject(j);if(p.has("stock")){tracked++;if(n(p,"stock")<=n(p,"lowStock"))low++;cost+=n(p,"stock")*n(p,"cost");value+=n(p,"stock")*n(p,"rate");}}LinearLayout stats=card(body);add(stats,txt("Tracked "+tracked+" · Low stock "+low,17,INK,true));add(stats,txt("Stock cost "+money(cost)+" · Sales value "+money(value),14,MUTED,false));for(int j=0;j<products.length();j++){JSONObject p=products.optJSONObject(j);LinearLayout c=card(body);add(c,txt(str(p,"name"),17,INK,true));add(c,txt(p.has("stock")?quantity(n(p,"stock"))+" "+str(p,"unit")+(n(p,"stock")<=n(p,"lowStock")?" · LOW STOCK":""):"Not tracked",13,MUTED,false));btn(c,"Manage stock",false,()->stockDialog(p));}}
    void stockDialog(JSONObject p){LinearLayout l=col();l.setPadding(dp(16),0,dp(16),0);EditText q=field(l,"Current physical quantity",quantity(n(p,"stock")),NUM),low=field(l,"Low stock warning",quantity(n(p,"lowStock")),NUM),cost=field(l,"Cost per unit ₹",quantity(n(p,"cost")),NUM);AlertDialog d=new AlertDialog.Builder(a).setTitle(str(p,"name")).setView(l).setNegativeButton("Cancel",null).setPositiveButton("Save",null).create();d.setOnShowListener(v->d.getButton(-1).setOnClickListener(w->safe(()->{JSONObject next=copy(db()),x=find(arr(next,"products"),str(p,"id"));put(x,"stock",stockRound(valNum(q)));put(x,"lowStock",stockRound(valNum(low)));put(x,"cost",round(valNum(cost)));store.commit(next);d.dismiss();show("inventory");})));d.show();}
    void reports(){title("Sales reports","Invoice-date totals, excluding quotations");LinearLayout buttons=row();for(String p:new String[]{"today","week","month","all"}){TextView b=button(p,period.equals(p),()->{period=p;show("reports");});weight(buttons,b);}add(body,buttons);gap(body,12);Calendar cal=Calendar.getInstance();cal.add(Calendar.DATE,-6);String week=new java.text.SimpleDateFormat("yyyy-MM-dd",Locale.US).format(cal.getTime()),now=today();double sales=0,paid=0,due=0,tax=0,discount=0;int count=0;Map<String,Double> days=new TreeMap<>(),products=new HashMap<>();JSONArray all=arr(db(),"invoices");for(int j=0;j<all.length();j++){JSONObject i=all.optJSONObject(j);String date=str(i,"date");if(quote(i)||(!period.equals("all")&&(date.compareTo(now)>0||!(period.equals("today")?date.equals(now):period.equals("week")?date.compareTo(week)>=0:date.startsWith(now.substring(0,7))))))continue;Totals t=new Totals(i);count++;sales+=t.total;paid+=t.paid;due+=t.due;tax+=t.tax;discount+=t.discount;days.put(date,(days.containsKey(date)?days.get(date):0)+t.total);JSONArray items=arr(i,"items");for(int k=0;k<items.length();k++){String name=str(items.optJSONObject(k),"name");products.put(name,(products.containsKey(name)?products.get(name):0)+n(t.lines.optJSONObject(k),"base"));}}LinearLayout c=card(body);for(String line:new String[]{"Sales "+money(sales),"Received "+money(paid),"Outstanding "+money(due),"GST "+money(tax),"Discounts "+money(discount),"Bills "+count})add(c,txt(line,17,INK,true));c=card(body);add(c,txt("Daily sales",18,INK,true));double max=1;for(double v:days.values())max=Math.max(max,v);for(Map.Entry<String,Double> e:days.entrySet()){add(c,txt(e.getKey()+" · "+money(e.getValue()),13,INK,false));ProgressBar bar=new ProgressBar(a,null,android.R.attr.progressBarStyleHorizontal);bar.setMax(1000);bar.setProgress((int)(1000*e.getValue()/max));add(c,bar);}c=card(body);add(c,txt("Top products · net of GST",18,INK,true));ArrayList<Map.Entry<String,Double>> sorted=new ArrayList<>(products.entrySet());Collections.sort(sorted,(x,y)->Double.compare(y.getValue(),x.getValue()));for(int k=0;k<Math.min(20,sorted.size());k++)add(c,txt(sorted.get(k).getKey()+" · "+money(sorted.get(k).getValue()),14,INK,false));add(body,txt("Received amounts reflect cumulative payments on bills in this period, not a cash-flow report.",12,MUTED,false));}
    void profile(){title("Business profile","Saved shop branding and invoice details");JSONObject b=copy(sub(db(),"business"));LinearLayout c=card(body);shopFields(c,b);bind(c,"Bill prefix",b,"prefix",TEXT);btn(c,"Save profile",true,()->safe(()->{require(!str(b,"name").isEmpty(),"Shop name required");JSONObject next=copy(db());put(next,"business",b);store.commit(next);a.tell("Profile saved");show("settings");}));}
