    void sign(JSONObject i,boolean global){LinearLayout l=col();l.setPadding(dp(12),dp(8),dp(12),dp(8));SignaturePad pad=new SignaturePad(a,global?arr(db(),"defaultSignature"):arr(i,"signature"),true);l.addView(pad,new LayoutParams(-1,dp(160)));pair(l,"Clear",pad::clear,"Undo",pad::undo);if(!global&&db().has("defaultSignature"))btn(l,"Use saved signature",false,()->pad.replace(arr(db(),"defaultSignature")));add(l,txt("Only use signatures you are authorised to use. Not a cryptographic PDF signature.",12,MUTED,false));AlertDialog d=new AlertDialog.Builder(a).setTitle("Authorised signature").setView(l).setNegativeButton("Cancel",null).setNeutralButton("Remove",null).setPositiveButton("Save",null).create();d.setOnShowListener(v->{d.getButton(-1).setOnClickListener(w->safe(()->{require(pad.valid(),"Draw a signature first");saveSignature(i,global,pad.strokes);d.dismiss();show(screen);}));d.getButton(-3).setOnClickListener(w->confirm("Remove signature?","Exported copies will not change.",()->safe(()->{saveSignature(i,global,null);d.dismiss();show(screen);})));});d.show();}
