    static final class SignaturePad extends View {
        JSONArray strokes=new JSONArray();JSONArray current;final boolean draw;final Paint pen=new Paint(Paint.ANTI_ALIAS_FLAG);
        SignaturePad(Context c,JSONArray initial,boolean canDraw){super(c);draw=canDraw;replace(initial);setContentDescription("Handwritten signature");pen.setColor(0xff152d55);pen.setStrokeWidth(4.5f);pen.setStrokeCap(Paint.Cap.ROUND);pen.setStrokeJoin(Paint.Join.ROUND);pen.setStyle(Paint.Style.STROKE);setBackgroundColor(0xfffffdf7);}
        void replace(JSONArray a){try{strokes=new JSONArray(a.toString());}catch(Exception e){strokes=new JSONArray();}current=null;invalidate();}
        void clear(){strokes=new JSONArray();current=null;invalidate();}
        void undo(){if(strokes.length()>0)strokes.remove(strokes.length()-1);current=null;invalidate();}
        boolean valid(){for(int j=0;j<strokes.length();j++){JSONArray s=strokes.optJSONArray(j);if(s!=null&&s.length()>1){JSONArray first=s.optJSONArray(0);for(int k=1;k<s.length();k++){JSONArray p=s.optJSONArray(k);if(p.optDouble(0)!=first.optDouble(0)||p.optDouble(1)!=first.optDouble(1))return true;}}}return false;}
        @Override protected void onDraw(Canvas c){super.onDraw(c);c.save();c.scale(getWidth()/600f,getHeight()/200f);for(int j=0;j<strokes.length();j++){JSONArray s=strokes.optJSONArray(j);if(s==null||s.length()==0)continue;Path path=new Path();for(int k=0;k<s.length();k++){JSONArray p=s.optJSONArray(k);float x=(float)p.optDouble(0),y=(float)p.optDouble(1);if(k==0)path.moveTo(x,y);else path.lineTo(x,y);if(s.length()==1)path.lineTo(x+0.1f,y);}c.drawPath(path,pen);}c.restore();}
        @Override public boolean onTouchEvent(android.view.MotionEvent e){if(!draw)return false;int action=e.getActionMasked();if(action==MotionEvent.ACTION_DOWN){getParent().requestDisallowInterceptTouchEvent(true);if(strokes.length()>=80)return true;current=new JSONArray();strokes.put(current);}if((action==MotionEvent.ACTION_DOWN||action==MotionEvent.ACTION_MOVE)&&current!=null){int n=0;for(int j=0;j<strokes.length();j++)n+=strokes.optJSONArray(j).length();if(n<1600)current.put(NativeStore.row(Math.max(0,Math.min(600,e.getX()*600/getWidth())),Math.max(0,Math.min(200,e.getY()*200/getHeight()))));invalidate();}if(action==MotionEvent.ACTION_UP||action==MotionEvent.ACTION_CANCEL){current=null;getParent().requestDisallowInterceptTouchEvent(false);}return true;}
    }
